package com.smart.ecommerce.service;
import com.smart.ecommerce.enums.OrderStatus;import java.util.*;import org.springframework.stereotype.Service;
@Service public class OrderStatusTransitionService { private static final Map<OrderStatus, Set<OrderStatus>> ALLOWED=Map.of(OrderStatus.PENDING,Set.of(OrderStatus.CONFIRMED,OrderStatus.CANCELLED),OrderStatus.CONFIRMED,Set.of(OrderStatus.PROCESSING,OrderStatus.CANCELLED),OrderStatus.PROCESSING,Set.of(OrderStatus.READY_FOR_DELIVERY,OrderStatus.CANCELLED),OrderStatus.READY_FOR_DELIVERY,Set.of(OrderStatus.COMPLETED),OrderStatus.COMPLETED,Set.of(),OrderStatus.CANCELLED,Set.of()); public void validate(OrderStatus from, OrderStatus to){ if(!ALLOWED.getOrDefault(from,Set.of()).contains(to)) throw new IllegalArgumentException("Invalid status transition from "+from+" to "+to); } public boolean canCustomerCancel(OrderStatus s){ return s==OrderStatus.PENDING; } public boolean canAdminCancel(OrderStatus s){ return s==OrderStatus.PENDING||s==OrderStatus.CONFIRMED||s==OrderStatus.PROCESSING; }}
